import { useEffect } from 'react';

export const useButtonKeyboardFocus = (
  buttonRef: React.MutableRefObject<HTMLButtonElement | undefined>,
  shouldFocus: boolean,
  onFocus: () => void,
) => {
  useEffect(() => {
    if (shouldFocus && buttonRef.current) {
      onFocus();
      buttonRef.current?.focus();
    }
  }, [buttonRef, shouldFocus, onFocus]);
};
